export const meta = {
  name: 'comprehensive-image-ip-audit',
  description: 'Open EVERY generated image in every task and flag any real-world brand/logo/trademark/trade-dress/real-person/real-venue baked into the pixels — the comprehensive IP sweep the sampled audits missed',
  phases: [{ title: 'Image IP audit' }],
}
const BASE = '/Users/dhiren/Downloads/Deccan/Adobe-Freelance-Leads'
const IDS = args
const SCHEMA = {
  type: 'object',
  properties: {
    task_id: { type: 'string' },
    images_checked: { type: 'integer' },
    clean: { type: 'boolean' },
    leaked: { type: 'array', items: { type: 'object', properties: {
      file: { type: 'string' }, what: { type: 'string' } }, required: ['file', 'what'] } },
  },
  required: ['task_id', 'images_checked', 'clean', 'leaked'],
}
const results = await parallel(IDS.map((id) => () => agent(
  `Comprehensive IP check of task ${id}'s generated IMAGES. The task's own FICTIONAL brand is fine; only REAL-WORLD IP is a leak.\n\n` +
  `1. bash: list the images -> \`ls -1 ${BASE}/input_assets_v3/${id}/assets/ | grep -iE '\\.(jpg|jpeg|png)$'\`.\n` +
  `2. OPEN AND LOOK AT every photoreal / product / lifestyle / portrait / retail / packaging / screen / signage image (skip pure vector logos/wordmarks of the task's own fictional brand and pure data files). Read them (the Read tool shows images). If there are many, check them all in batches — do not sample; the whole point is to catch what sampling missed.\n` +
  `3. Flag any image where the PIXELS contain: a real brand name / logo / wordmark (e.g. Lay's, Katz's, Nike, Apple, Gymshark, Rogue, TYR, SBD, Upper Deck, Topps, Pokemon, GOODTHREADS), real trade dress / product get-up (e.g. Marshall amp livery), real trademarked characters or card art, a real athlete/celebrity name or likeness, or real venue signage at a real address. On-garment/on-equipment/background brand logos count. The task's OWN invented brand is NOT a leak.\n\n` +
  `Return images_checked (how many you actually opened), clean (true only if NONE leak), and leaked = [{file, what}] naming each offending file and exactly what real IP appears. Be thorough and strict — this is the definitive sweep.`,
  { agentType: 'general-purpose', phase: 'Image IP audit', label: `ip:${id}`, schema: SCHEMA }
)))
const r = results.filter(Boolean)
const leakTasks = r.filter(x => !x.clean)
return {
  audited: r.length,
  clean_tasks: r.filter(x => x.clean).length,
  leak_tasks: leakTasks.length,
  total_leaked_files: leakTasks.reduce((s, x) => s + (x.leaked || []).length, 0),
  leaks: leakTasks.map(x => ({ id: x.task_id, files: (x.leaked || []).map(l => l.file), what: (x.leaked || []).map(l => l.what) })),
}
